using System.Text;
using Haldus.Generators.Infrastructure;
using Haldus.Generators.Model;

namespace Haldus.Generators.Emit;

/// <summary>Bir kaynağın entity yarısını, DTO'larını ve endpoint'lerini üretir.</summary>
internal static class ResourceEmitter
{
    private const string Header = """
        // <auto-generated/>
        #nullable enable


        """;

    public static string QualifiedName(ResourceModel resource, string entityNamespace) =>
        entityNamespace.Length == 0
            ? $"global::{resource.EntityName}"
            : $"global::{entityNamespace}.{resource.EntityName}";

    /// <summary>Üretilecek bir şey yoksa (kullanıcı Id'yi kendi yazdıysa) <c>null</c> döner.</summary>
    public static string? EmitEntity(ResourceModel resource, string entityNamespace)
    {
        if (resource.IdDeclared)
        {
            return null;
        }

        // Kullanıcı sınıfı yazdıysa erişim belirleyicisi onun bildiriminden gelir.
        var accessibility = resource.EntityDeclared ? string.Empty : "public ";

        return $$"""
            {{Header}}{{NamespaceLine(entityNamespace)}}

            {{accessibility}}partial class {{resource.EntityName}}
            {
                public {{resource.IdType}} Id { get; set; }
            }

            """;
    }

    public static string EmitDtos(ResourceModel resource, string entityNamespace)
    {
        var builder = new StringBuilder();
        builder.Append(Header);
        builder.AppendLine(NamespaceLine(entityNamespace));

        builder.AppendLine();
        builder.AppendLine($"public sealed partial record {resource.EntityName}Response");
        builder.AppendLine("{");
        builder.AppendLine($"    public required {resource.IdType} Id {{ get; init; }}");
        foreach (var property in resource.Properties)
        {
            builder.AppendLine($"    public required {property.Type} {property.Name} {{ get; init; }}");
        }

        builder.AppendLine("}");

        AppendRequest(builder, $"Create{resource.EntityName}Request", resource);
        AppendRequest(builder, $"Update{resource.EntityName}Request", resource);

        return builder.ToString();
    }

    public static string EmitEndpoints(ResourceModel resource, string entityNamespace)
    {
        var entity = resource.EntityName;
        var plural = Naming.Pluralize(entity);
        var route = "/" + Naming.ToKebabCase(plural);
        var idRoute = resource.IdKind switch
        {
            IdKind.Int32 => "/{id:int}",
            IdKind.Int64 => "/{id:long}",
            _ => "/{id:guid}",
        };

        var writable = resource.Properties.Where(property => property.IsWritable).ToArray();

        var responseAssignments = string.Join(
            ", ",
            new[] { "Id = item.Id" }.Concat(resource.Properties.Select(property => $"{property.Name} = item.{property.Name}")));

        var createAssignments = string.Join(
            ", ",
            (resource.IdKind == IdKind.Guid ? ["Id = global::System.Guid.CreateVersion7()"] : Array.Empty<string>())
                .Concat(writable.Select(property => $"{property.Name} = request.{property.Name}")));

        var updateAssignments = string.Join(
            "\n",
            writable.Select(property => $"        entity.{property.Name} = request.{property.Name};"));

        return $$"""
            {{Header}}using System.Linq;
            using Microsoft.AspNetCore.Builder;
            using Microsoft.AspNetCore.Http;
            using Microsoft.AspNetCore.Routing;
            using Microsoft.EntityFrameworkCore;

            {{NamespaceLine(entityNamespace)}}

            public static partial class {{entity}}Endpoints
            {
                public static global::Microsoft.AspNetCore.Routing.RouteGroupBuilder Map(
                    global::Microsoft.AspNetCore.Routing.IEndpointRouteBuilder endpoints)
                {
                    var group = endpoints.MapGroup("{{route}}").WithTags("{{plural}}");

                    group.MapGet("/", ListAsync)
                        .WithName("List{{plural}}");

                    group.MapGet("{{idRoute}}", GetAsync)
                        .WithName("Get{{entity}}")
                        .ProducesProblem(404);

                    group.MapPost("/", CreateAsync)
                        .WithName("Create{{entity}}")
                        .AddEndpointFilter<global::Haldus.HaldusValidationFilter<Create{{entity}}Request>>()
                        .ProducesValidationProblem();

                    group.MapPut("{{idRoute}}", UpdateAsync)
                        .WithName("Update{{entity}}")
                        .AddEndpointFilter<global::Haldus.HaldusValidationFilter<Update{{entity}}Request>>()
                        .ProducesValidationProblem()
                        .ProducesProblem(404);

                    group.MapDelete("{{idRoute}}", DeleteAsync)
                        .WithName("Delete{{entity}}")
                        .ProducesProblem(404);

                    return group;
                }

                private static async global::System.Threading.Tasks.Task<global::Microsoft.AspNetCore.Http.HttpResults.Ok<global::Haldus.PagedResult<{{entity}}Response>>> ListAsync(
                    [global::Microsoft.AspNetCore.Http.AsParameters] global::Haldus.PageRequest page,
                    global::Haldus.IHaldusDbContextProvider contexts,
                    global::System.Threading.CancellationToken cancellationToken)
                {
                    var query = contexts.For<{{entity}}>().Set<{{entity}}>().AsNoTracking();
                    var totalCount = await query.LongCountAsync(cancellationToken);
                    var items = await query
                        .OrderBy(item => item.Id)
                        .Skip(page.Skip)
                        .Take(page.PageSizeOrDefault)
                        .Select(item => new {{entity}}Response { {{responseAssignments}} })
                        .ToListAsync(cancellationToken);

                    return global::Microsoft.AspNetCore.Http.TypedResults.Ok(
                        new global::Haldus.PagedResult<{{entity}}Response>(items, page.PageOrDefault, page.PageSizeOrDefault, totalCount));
                }

                private static async global::System.Threading.Tasks.Task<global::Microsoft.AspNetCore.Http.HttpResults.Results<global::Microsoft.AspNetCore.Http.HttpResults.Ok<{{entity}}Response>, global::Microsoft.AspNetCore.Http.HttpResults.ProblemHttpResult>> GetAsync(
                    {{resource.IdType}} id,
                    global::Haldus.IHaldusDbContextProvider contexts,
                    global::Haldus.IHaldusMessages messages,
                    global::System.Threading.CancellationToken cancellationToken)
                {
                    var entity = await contexts.For<{{entity}}>().Set<{{entity}}>()
                        .AsNoTracking()
                        .FirstOrDefaultAsync(item => item.Id == id, cancellationToken);

                    if (entity is null)
                    {
                        return global::Haldus.HaldusProblems.NotFound(messages, "{{entity}}", id);
                    }

                    return global::Microsoft.AspNetCore.Http.TypedResults.Ok(ToResponse(entity));
                }

                private static async global::System.Threading.Tasks.Task<global::Microsoft.AspNetCore.Http.HttpResults.Created<{{entity}}Response>> CreateAsync(
                    Create{{entity}}Request request,
                    global::Microsoft.AspNetCore.Http.HttpContext httpContext,
                    global::Haldus.IHaldusDbContextProvider contexts,
                    global::System.Threading.CancellationToken cancellationToken)
                {
                    var entity = new {{entity}} { {{createAssignments}} };

                    var context = contexts.For<{{entity}}>();
                    context.Set<{{entity}}>().Add(entity);
                    await context.SaveChangesAsync(cancellationToken);

                    var location = $"{httpContext.Request.PathBase}{httpContext.Request.Path.Value?.TrimEnd('/')}/{entity.Id}";
                    return global::Microsoft.AspNetCore.Http.TypedResults.Created(location, ToResponse(entity));
                }

                private static async global::System.Threading.Tasks.Task<global::Microsoft.AspNetCore.Http.HttpResults.Results<global::Microsoft.AspNetCore.Http.HttpResults.Ok<{{entity}}Response>, global::Microsoft.AspNetCore.Http.HttpResults.ProblemHttpResult>> UpdateAsync(
                    {{resource.IdType}} id,
                    Update{{entity}}Request request,
                    global::Haldus.IHaldusDbContextProvider contexts,
                    global::Haldus.IHaldusMessages messages,
                    global::System.Threading.CancellationToken cancellationToken)
                {
                    var context = contexts.For<{{entity}}>();
                    var entity = await context.Set<{{entity}}>().FirstOrDefaultAsync(item => item.Id == id, cancellationToken);

                    if (entity is null)
                    {
                        return global::Haldus.HaldusProblems.NotFound(messages, "{{entity}}", id);
                    }

            {{updateAssignments}}
                    await context.SaveChangesAsync(cancellationToken);

                    return global::Microsoft.AspNetCore.Http.TypedResults.Ok(ToResponse(entity));
                }

                private static async global::System.Threading.Tasks.Task<global::Microsoft.AspNetCore.Http.HttpResults.Results<global::Microsoft.AspNetCore.Http.HttpResults.NoContent, global::Microsoft.AspNetCore.Http.HttpResults.ProblemHttpResult>> DeleteAsync(
                    {{resource.IdType}} id,
                    global::Haldus.IHaldusDbContextProvider contexts,
                    global::Haldus.IHaldusMessages messages,
                    global::System.Threading.CancellationToken cancellationToken)
                {
                    var context = contexts.For<{{entity}}>();
                    var entity = await context.Set<{{entity}}>().FirstOrDefaultAsync(item => item.Id == id, cancellationToken);

                    if (entity is null)
                    {
                        return global::Haldus.HaldusProblems.NotFound(messages, "{{entity}}", id);
                    }

                    context.Set<{{entity}}>().Remove(entity);
                    await context.SaveChangesAsync(cancellationToken);

                    return global::Microsoft.AspNetCore.Http.TypedResults.NoContent();
                }

                private static {{entity}}Response ToResponse({{entity}} item) => new() { {{responseAssignments}} };
            }

            """;
    }

    private static void AppendRequest(StringBuilder builder, string name, ResourceModel resource)
    {
        builder.AppendLine();
        builder.AppendLine($"public sealed partial record {name}");
        builder.AppendLine("{");

        var first = true;
        foreach (var property in resource.Properties)
        {
            if (!property.IsWritable)
            {
                continue;
            }

            if (!first)
            {
                builder.AppendLine();
            }

            first = false;

            foreach (var attribute in property.ValidationAttributes)
            {
                builder.AppendLine($"    [{attribute}]");
            }

            var initializer = property.IsNonNullableReference ? " = default!;" : string.Empty;
            builder.AppendLine($"    public {property.Type} {property.Name} {{ get; init; }}{initializer}");
        }

        builder.AppendLine("}");
    }

    private static string NamespaceLine(string entityNamespace) =>
        entityNamespace.Length == 0 ? string.Empty : $"namespace {entityNamespace};";
}
